import{_ as e,o as t,c as l,ae as o}from"./chunks/framework.RRduUuAx.js";const _=JSON.parse('{"title":"注销账户说明","description":"","frontmatter":{},"headers":[],"relativePath":"v1/zh/help/account-deletion.md","filePath":"v1/zh/help/account-deletion.md"}'),i={name:"v1/zh/help/account-deletion.md"};function r(n,a,c,h,d,s){return t(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="注销账户说明" tabindex="-1">注销账户说明 <a class="header-anchor" href="#注销账户说明" aria-label="Permalink to &quot;注销账户说明&quot;">​</a></h1><p>注销账户会清空该账号在云端与本机的所有数据，请在操作前确认你已理解并接受以下影响。</p><h2 id="会发生什么" tabindex="-1">会发生什么 <a class="header-anchor" href="#会发生什么" aria-label="Permalink to &quot;会发生什么&quot;">​</a></h2><ul><li>云端数据：清空该账号的云同步数据（包括但不限于账本、账单、分类、标签等）。</li><li>本机数据：清空该账号在当前设备上的本地数据（包括离线数据）。</li><li>不可撤销：注销执行后无法恢复已删除的数据。</li></ul><h2 id="会员订阅是否受影响" tabindex="-1">会员订阅是否受影响 <a class="header-anchor" href="#会员订阅是否受影响" aria-label="Permalink to &quot;会员订阅是否受影响&quot;">​</a></h2><p>注销账户不会影响你的订阅有效期。</p><p>如果你是付费会员，注销后重新登录，并在应用内点击「恢复购买」，仍可恢复会员状态（以应用商店的订阅状态为准）。</p><h2 id="建议" tabindex="-1">建议 <a class="header-anchor" href="#建议" aria-label="Permalink to &quot;建议&quot;">​</a></h2><ul><li>如你需要保留数据，请先在应用内完成导出/备份（如有）。</li><li>注销后再重新登录将视为新环境，你需要重新同步/导入数据。</li></ul>',9)])])}const p=e(i,[["render",r]]);export{_ as __pageData,p as default};
